      const rel = contentCatalog.resolvePage('index.adoc', { component: component.name })
      if (!rel) return
      contentCatalog.addFile({
        src: { component: component.name, version: '', module: 'ROOT', family: 'alias', relative: 'index.adoc' },
        rel,
      })
    })
